<script lang="ts">import {publicHref,publicLabels,type PublicRow} from '$lib/content/public';let {items,variant='list'}:{items:PublicRow[];variant?:'list'|'featured'|'projects'|'moments'}=$props();const date=(value:string|Date)=>new Date(value).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'});const updated=(item:PublicRow)=>!!item.update_at&&new Date(item.update_at).getTime()>new Date(item.first_published_at).getTime();const statusLabel=(value:unknown)=>({completed:'已完成','in-progress':'进行中',paused:'暂停',stopped:'已停止'})[String(value)]??'';</script>
{#if !items.length}<div class="empty"><span aria-hidden="true">✦</span><p>暂无公开内容。</p></div>{:else}<ul class={`${variant} content-list`}>{#each items as item,index}<li class:lead={variant==='list'&&index===0}>{#if variant==='projects'}<div class:placeholder={!(typeof item.payload.cover==='string'&&item.payload.cover)} class="visual">{#if typeof item.payload.cover==='string'&&item.payload.cover}<img src={`/media/public/${item.payload.cover}`} alt="" width="640" height="400" loading="lazy" />{:else}<span aria-hidden="true">{item.title?.slice(0,1)||'作'}</span>{/if}</div>{/if}<div class="item-copy"><p class="meta"><span class="type">{publicLabels[item.type]}</span><span aria-hidden="true">·</span>{updated(item)?'更新于 ':''}{date(item.update_at??item.first_published_at??item.published_at)}</p><a class="item-title" href={publicHref(item.type,item.slug)}><h3>{item.title||item.summary||publicLabels[item.type]}</h3></a>{#if item.summary}<p class="summary">{item.summary}</p>{/if}{#if variant==='projects'}<p class="project-status">{statusLabel(item.payload.projectStatus)}</p>{/if}</div></li>{/each}</ul>{/if}
<style>
 ul{list-style:none;padding:0;margin:0}li{position:relative;display:grid;grid-template-columns:minmax(0,1fr);gap:16px;padding:20px 0;border-bottom:1px solid var(--line);min-width:0}li:first-child{border-top:1px solid var(--line)}li.lead{margin:0;padding-inline:0;background:none;border-radius:0}li.lead .item-title h3{font-size:1.25rem}.item-copy{min-width:0}.meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:0 0 7px;color:var(--muted);font:0.75rem/1.4 'DM Mono',monospace}.type{color:var(--primary);font-weight:700}.item-title{color:var(--text);text-decoration:none}.item-title h3{margin:0;font-family:inherit;font-size:1.125rem;line-height:1.4}.item-title:hover h3,.content-list li:hover .item-title h3{color:var(--primary)}.summary{margin:8px 0 0;color:var(--muted);display:-webkit-box;display:box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.item-arrow{display:none}.project-status{display:inline-flex;max-width:calc(100% - 48px);margin:12px 0 0;padding:4px 9px;border-radius:999px;background:var(--soft);color:var(--focus);font-size:0.8125rem}.empty{display:grid;place-items:center;gap:4px;padding:44px 20px;border:1px dashed var(--border);border-radius:var(--radius-md);color:var(--muted)}.empty span{color:var(--primary);font-size:1.375rem}.empty p{margin:0}.featured{display:grid;grid-template-columns:1.35fr 1fr;gap:0 32px;border-top:1px solid var(--line)}.featured li{padding:22px 0}.featured li:first-child{grid-row:span 2;padding:22px 0;background:none;border:0;border-bottom:1px solid var(--line);border-radius:0;margin-right:0}.featured li:first-child .item-title h3{font-size:1.5rem}.content-list{position:relative}.moments li{grid-template-columns:112px minmax(0,1fr) auto;padding-block:24px}.moments .meta{align-content:start;display:block;line-height:1.8}.moments .meta .type{display:block;margin-bottom:3px}.moments .item-title h3{font-size:1.25rem}.moments li::before{content:'';position:absolute;left:102px;top:0;bottom:0;border-left:1px dashed var(--soft-strong)}.moments li::after{content:'';position:absolute;left:98px;top:29px;width:9px;height:9px;border-radius:50%;background:var(--accent-pink);box-shadow:0 0 0 4px var(--surface)}.projects{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;border:0}.projects li{display:flex;flex-direction:column;gap:10px;padding:0;border:1px solid color-mix(in srgb,var(--line) 70%,transparent);border-radius:16px;overflow:hidden;background:color-mix(in srgb,var(--surface) 48%,transparent);box-shadow:none;transition:border-color .2s ease,transform .2s ease,background .2s ease}.projects li:hover{border-color:color-mix(in srgb,var(--primary) 40%,var(--line));background:color-mix(in srgb,var(--surface) 70%,var(--soft));transform:translateY(-2px)}.projects li:first-child{border-top:1px solid var(--line)}.projects .item-copy{padding:16px 18px 24px}.visual{aspect-ratio:16/6;background:linear-gradient(135deg,var(--soft),var(--soft-strong));display:grid;place-items:center;position:relative;overflow:hidden;color:var(--primary);font-size:3rem;font-weight:800}.visual.placeholder{background:linear-gradient(135deg,var(--soft),var(--canvas))}.visual.placeholder span{font-family:var(--font-display);font-size:3.625rem;color:var(--primary);opacity:.8}.visual img{width:100%;height:100%;object-fit:cover;position:relative;z-index:1}.projects .meta{margin-bottom:8px}
 .content-list:not(.projects) li:hover{background:color-mix(in srgb,var(--primary) 4%,transparent);box-shadow:none}.content-list:not(.projects) li{border-radius:12px;transition:background .2s ease}@media(max-width:767px){.moments li{grid-template-columns:1fr auto;padding-left:22px}.moments li::before{left:5px}.moments li::after{left:1px;top:29px}.moments .meta{grid-column:1/-1;display:flex;gap:8px}.moments .meta .type{display:inline}.moments .item-title h3{font-size:1.125rem}li.lead{margin:0;padding-inline:0}li.lead .item-title h3{font-size:1.125rem}.featured,.projects{display:block}.featured li:first-child{padding:20px 0}.featured li:first-child .item-title h3{font-size:1.3125rem}.projects li{margin-bottom:14px}.projects .item-copy{padding:16px 16px 24px}.item-title h3{font-size:1.125rem}}
